import React, { useState } from 'react';
import './Services.css';

function Services() {
  const services = [
    {
      id: 1,
      title: '🔄 Đổi Mật Khẩu',
      description: 'Hỗ trợ đổi mật khẩu nếu quên hoặc cần bảo mật',
      price: 'Miễn Phí',
      priceValue: 0
    },
    {
      id: 2,
      title: '🔐 Xác Minh 2 Lớp',
      description: 'Bảo vệ tài khoản với xác minh 2 lớp',
      price: 'Miễn Phí',
      priceValue: 0
    },
    {
      id: 3,
      title: '📧 Khôi Phục Email',
      description: 'Giúp khôi phục email tài khoản',
      price: '50,000 đ',
      priceValue: 50000
    },
    {
      id: 4,
      title: '🎁 Gamepass',
      description: 'Mua gamepass cho game của bạn',
      price: 'Liên Hệ',
      priceValue: null
    },
    {
      id: 5,
      title: '💎 Robux',
      description: 'Mua Robux trực tiếp vào tài khoản',
      price: 'Liên Hệ',
      priceValue: null
    },
    {
      id: 6,
      title: '👤 Đổi Tên Acc',
      description: 'Hỗ trợ đổi tên tài khoản Roblox',
      price: '100,000 đ',
      priceValue: 100000
    }
  ];

  const [selectedService, setSelectedService] = useState(null);
  const [showForm, setShowForm] = useState(false);
  const [formData, setFormData] = useState({
    service: '',
    username: '',
    password: '',
    notes: ''
  });

  const handleServiceClick = (service) => {
    setSelectedService(service);
    setShowForm(true);
    setFormData({
      service: service.title,
      username: '',
      password: '',
      notes: ''
    });
  };

  const handleInputChange = (e) => {
    const { name, value } = e.target;
    setFormData({ ...formData, [name]: value });
  };

  const handleSubmit = (e) => {
    e.preventDefault();
    if (!selectedService || !formData.username || !formData.password) {
      alert('Vui lòng điền đầy đủ thông tin');
      return;
    }
    const priceText = selectedService.priceValue !== null 
      ? selectedService.priceValue === 0 
        ? 'Miễn Phí' 
        : `${selectedService.priceValue.toLocaleString('vi-VN')}đ`
      : 'Liên Hệ';
    alert(`Đặt dịch vụ ${selectedService.title} thành công!\nGiá: ${priceText}`);
    setSelectedService(null);
    setShowForm(false);
    setFormData({ service: '', username: '', password: '', notes: '' });
  };

  const handleBack = () => {
    setSelectedService(null);
    setShowForm(false);
    setFormData({ service: '', username: '', password: '', notes: '' });
  };

  const getTotalPrice = () => {
    if (!selectedService || selectedService.priceValue === null) {
      return 'Liên Hệ';
    }
    if (selectedService.priceValue === 0) {
      return 'Miễn Phí';
    }
    return `${selectedService.priceValue.toLocaleString('vi-VN')}đ`;
  };

  return (
    <div className="services-container">
      <h1>🛠️ DỊCH VỤ KHÁC</h1>
      <p className="subtitle">Các dịch vụ bổ sung để hỗ trợ tài khoản của bạn</p>

      {!showForm ? (
        <div className="services-grid">
          {services.map(service => (
            <div key={service.id} className="service-card">
              <h3>{service.title}</h3>
              <p>{service.description}</p>
              <div className="service-footer">
                <span className="price">{service.price}</span>
                <button 
                  className="btn-order"
                  onClick={() => handleServiceClick(service)}
                >
                  Đặt Hàng
                </button>
              </div>
            </div>
          ))}
        </div>
      ) : (
        <div className="service-detail">
          <button className="btn-back" onClick={handleBack}>← Quay lại</button>
          
          <h2>{selectedService?.title}</h2>
          
          <div className="service-detail-content">
            <div className="service-info-card">
              <h3>Thông tin dịch vụ</h3>
              <p>{selectedService?.description}</p>
              <div className="service-price-info">
                <span className="price-label">Giá:</span>
                <span className="price-value">{selectedService?.price}</span>
              </div>
            </div>

            <form onSubmit={handleSubmit} className="service-form">
              <div className="form-row">
                <div className="form-group">
                  <label>Dịch vụ (*)</label>
                  <input 
                    type="text" 
                    value={formData.service} 
                    disabled 
                  />
                </div>

                <div className="form-group">
                  <label>Thành tiền</label>
                  <input 
                    type="text" 
                    value={getTotalPrice()} 
                    disabled 
                  />
                </div>
              </div>

              <div className="form-row">
                <div className="form-group full-width">
                  <label>Tên đăng nhập roblox (*)</label>
                  <input
                    type="text"
                    name="username"
                    value={formData.username}
                    onChange={handleInputChange}
                    placeholder="Nhập tên tài khoản Roblox"
                    required
                  />
                </div>
              </div>

              <div className="form-row">
                <div className="form-group full-width">
                  <label>Mật khẩu đăng nhập roblox (*)</label>
                  <input
                    type="password"
                    name="password"
                    value={formData.password}
                    onChange={handleInputChange}
                    placeholder="Nhập mật khẩu"
                    required
                  />
                </div>
              </div>

              <div className="form-row">
                <div className="form-group full-width">
                  <label>Ghi chú đơn hàng nếu có</label>
                  <textarea
                    name="notes"
                    value={formData.notes}
                    onChange={handleInputChange}
                    placeholder="Ghi chú thêm nếu có"
                    rows="5"
                  ></textarea>
                </div>
              </div>

              <button type="submit" className="btn-submit">Đặt Hàng</button>
            </form>
          </div>
        </div>
      )}
    </div>
  );
}

export default Services;
